<?php

namespace Modules\Attendance\Controllers;

use Core\Database;
use Modules\Attendance\Models\Attendance;
use Modules\Attendance\Models\AttendanceCorrection;
use Modules\Attendance\Support\AttendanceAccess;
use Modules\Authentication\Support\Request;

class AttendanceController
{
    private function auth(): array { $a=AttendanceAccess::authenticated();return isset($a['error'])?['success'=>false,'message'=>$a['error'],'status'=>$a['status']]:$a; }
    private function validDate(string $v): bool { $d=\DateTime::createFromFormat('Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v; }
    private function validTime(?string $v): bool { return $v===null||$v===''||(bool)preg_match('/^([01]\\d|2[0-3]):[0-5]\\d(?::[0-5]\\d)?$/',$v); }
    private function oneEmployee(string $id): ?array { $s=Database::connection()->prepare('SELECT e.employee_id,e.employee_code,e.full_name,d.department_name department,ds.designation_name designation,wl.location_name branch FROM employees e LEFT JOIN departments d ON d.department_id=e.department_id LEFT JOIN designations ds ON ds.designation_id=e.designation_id LEFT JOIN work_locations wl ON wl.work_location_id=e.work_location_id WHERE e.employee_id=? LIMIT 1');$s->execute([$id]);return $s->fetch()?:null; }
    private function presentEmployee(array $e): array { $n=(string)$e['full_name'];return ['id'=>$e['employee_id'],'employeeId'=>$e['employee_id'],'code'=>$e['employee_code'],'name'=>$n,'employeeCode'=>$e['employee_code'],'role'=>$e['designation']??'Employee','department'=>$e['department']??'Unassigned','branch'=>$e['branch']??'Unassigned','avatar'=>strtoupper(substr($n,0,1).(str_contains($n,' ')?substr(strrchr($n,' '),1,1):''))]; }
    private function employees(array $ids): array { if(!$ids)return [];$s=Database::connection()->prepare('SELECT e.employee_id,e.employee_code,e.full_name,d.department_name department,ds.designation_name designation,wl.location_name branch FROM employees e LEFT JOIN departments d ON d.department_id=e.department_id LEFT JOIN designations ds ON ds.designation_id=e.designation_id LEFT JOIN work_locations wl ON wl.work_location_id=e.work_location_id WHERE e.employee_id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY e.full_name');$s->execute($ids);return array_map([$this,'presentEmployee'],$s->fetchAll()); }
    private function presentRecord(array $r): array { $n=(string)($r['employee_name']??'');$d=(string)$r['attendance_date'];return ['id'=>(string)$r['id'],'employeeId'=>$r['employee_id'],'employeeCode'=>$r['employee_code']??null,'employeeName'=>$n,'role'=>$r['designation']??'Employee','department'=>$r['department']??'Unassigned','branch'=>$r['branch']??'Unassigned','avatar'=>strtoupper(substr($n,0,1).(str_contains($n,' ')?substr(strrchr($n,' '),1,1):'')),'date'=>$d.'T00:00:00','checkIn'=>$r['check_in']?$d.'T'.$r['check_in']:null,'checkOut'=>$r['check_out']?$d.'T'.$r['check_out']:null,'breakMinutes'=>(int)$r['break_minutes'],'breakStartedAt'=>$r['break_started_at']??null,'workingHours'=>(float)$r['working_hours'],'overtime'=>(float)$r['overtime'],'status'=>$r['status'],'shift'=>$r['shift'],'remarks'=>$r['remarks'],'isVirtual'=>false]; }
    private function presentCorrection(array $r): array { return ['id'=>(string)$r['id'],'employeeId'=>$r['employee_id'],'employeeCode'=>$r['employee_code']??null,'employeeName'=>$r['employee_name']??'Employee','department'=>$r['department']??'Unassigned','designation'=>$r['designation']??'Employee','date'=>$r['correction_date'],'requestedCheckIn'=>$r['requested_check_in'],'requestedCheckOut'=>$r['requested_check_out'],'reason'=>$r['reason'],'status'=>$r['status'],'submittedOn'=>$r['submitted_on'],'approverName'=>$r['approver_name']??null,'reviewRemarks'=>$r['review_remarks']??null,'reviewedAt'=>$r['reviewed_at']??null]; }
    private function approver(array $u,string $id): ?string { $role=AttendanceAccess::role($u);if($role==='SALES_EXECUTIVE'){$s=Database::connection()->prepare('SELECT reporting_manager_id FROM employees WHERE employee_id=?');$s->execute([$id]);return $s->fetchColumn()?:null;}$wanted=$role==='ASM'?'HR':($role==='HR'?'ADMIN':null);if(!$wanted)return null;$s=Database::connection()->prepare("SELECT e.employee_id FROM users u JOIN employees e ON e.employee_id=u.employee_id WHERE UPPER(u.role)=? AND LOWER(u.status) NOT IN ('inactive','disabled','suspended') LIMIT 1");$s->execute([$wanted]);return $s->fetchColumn()?:null; }
    private function hours(array $r): array { if(empty($r['check_in'])||empty($r['check_out']))return ['working_hours'=>0,'overtime'=>0];$seconds=max(0,strtotime($r['attendance_date'].' '.$r['check_out'])-strtotime($r['attendance_date'].' '.$r['check_in'])-((int)$r['break_minutes']*60));$h=round($seconds/3600,2);return ['working_hours'=>$h,'overtime'=>max(0,round($h-8,2))]; }
    private function virtualRecord(array $employee,string $date,string $status,string $remarks): array { return ['id'=>"virtual-{$status}-{$employee['id']}-{$date}",'employeeId'=>$employee['id'],'employeeCode'=>$employee['employeeCode'],'employeeName'=>$employee['name'],'role'=>$employee['role'],'department'=>$employee['department'],'branch'=>$employee['branch'],'avatar'=>$employee['avatar'],'date'=>$date.'T00:00:00','checkIn'=>null,'checkOut'=>null,'breakMinutes'=>0,'breakStartedAt'=>null,'workingHours'=>0,'overtime'=>0,'status'=>$status,'shift'=>'General Shift','remarks'=>$remarks,'isVirtual'=>true]; }
    private function supplementStatuses(array $records,array $employees,string $from,string $to): array { try { $byEmployee=[];foreach($employees as $employee)$byEmployee[$employee['id']]=$employee;$existing=[];foreach($records as $record)$existing[$record['employeeId'].'|'.substr($record['date'],0,10)]=true;$ids=array_keys($byEmployee);if(!$ids)return $records;$marks=implode(',',array_fill(0,count($ids),'?'));$db=Database::connection();$leaves=$db->prepare("SELECT employee_id,start_date,end_date,day_type FROM leave_requests WHERE status='Approved' AND employee_id IN ($marks) AND start_date <= ? AND end_date >= ?");$leaves->execute([...$ids,$to,$from]);foreach($leaves->fetchAll() as $leave){$day=new \DateTime($leave['start_date']);$end=new \DateTime($leave['end_date']);while($day<=$end){$date=$day->format('Y-m-d');$key=$leave['employee_id'].'|'.$date;if((int)$day->format('N')<6&&!isset($existing[$key])){$records[]=$this->virtualRecord($byEmployee[$leave['employee_id']],$date,$leave['day_type']==='Full Day'?'Leave':'Half Day','Approved leave');$existing[$key]=true;}$day->modify('+1 day');}}$holidays=$db->prepare('SELECT title,holiday_date,location FROM company_holidays WHERE holiday_date BETWEEN ? AND ?');$holidays->execute([$from,$to]);foreach($holidays->fetchAll() as $holiday)foreach($employees as $employee){$key=$employee['id'].'|'.$holiday['holiday_date'];if(!isset($existing[$key])&&($holiday['location']==='All'||strcasecmp($holiday['location'],$employee['branch'])===0)){$records[]=$this->virtualRecord($employee,$holiday['holiday_date'],'Holiday',$holiday['title']);$existing[$key]=true;}}usort($records,fn($left,$right)=>strcmp($right['date'],$left['date']));return $records;}catch(\Throwable){return $records;} }
    private function restrictedReason(string $employeeId,string $date): ?string { try {$db=Database::connection();$leave=$db->prepare("SELECT 1 FROM leave_requests WHERE employee_id=? AND status='Approved' AND ? BETWEEN start_date AND end_date LIMIT 1");$leave->execute([$employeeId,$date]);if($leave->fetchColumn())return 'You are on approved leave today.';$employee=$this->oneEmployee($employeeId);$holiday=$db->prepare("SELECT title FROM company_holidays WHERE holiday_date=? AND (location='All' OR location=?) LIMIT 1");$holiday->execute([$date,$employee['branch']??'']);return $holiday->fetchColumn()?'Today is a company holiday.':null;}catch(\Throwable){return null;} }
    private function notify(string $employeeId,string $title,string $message,string $type='info'): void { try { Database::connection()->prepare('INSERT INTO attendance_notifications (employee_id,title,message,notification_type) VALUES (?,?,?,?)')->execute([$employeeId,$title,$message,$type]); } catch (\Throwable) {} }

    public function overview(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;$ids=AttendanceAccess::visibleEmployeeIds($a['user']);$me=AttendanceAccess::employeeId($a['user']);$from=(string)Request::input('from',date('Y-m-d',strtotime('-90 days')));$to=(string)Request::input('to',date('Y-m-d'));if(!$this->validDate($from)||!$this->validDate($to)||$from>$to)return ['success'=>false,'message'=>'Provide a valid date range.','status'=>422];$employees=$this->employees($ids);$records=$this->supplementStatuses(array_map([$this,'presentRecord'],Attendance::findMany($ids,$from,$to)),$employees,$from,$to);$today=array_values(array_filter($records,fn($r)=>substr($r['date'],0,10)===date('Y-m-d')));return ['success'=>true,'data'=>['role'=>AttendanceAccess::role($a['user']),'currentEmployee'=>$me&&$this->oneEmployee($me)?$this->presentEmployee($this->oneEmployee($me)):null,'employees'=>$employees,'records'=>$records,'todayRecords'=>$today,'corrections'=>array_map([$this,'presentCorrection'],AttendanceCorrection::findMany($ids))]]; }
    public function myToday(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;$id=AttendanceAccess::employeeId($a['user']);if(!$id)return ['success'=>false,'message'=>'Your employee profile is not linked.','status'=>422];$r=Attendance::findByEmployeeAndDate($id,date('Y-m-d'));return ['success'=>true,'record'=>$r?$this->presentRecord($r):null]; }
    public function notifications(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;$id=AttendanceAccess::employeeId($a['user']);if(!$id)return ['success'=>false,'message'=>'Your employee profile is not linked.','status'=>422];try{$s=Database::connection()->prepare('SELECT id,title,message,notification_type,created_at FROM attendance_notifications WHERE employee_id=? ORDER BY created_at DESC,id DESC LIMIT 20');$s->execute([$id]);$items=array_map(static fn($row)=>['id'=>(string)$row['id'],'title'=>$row['title'],'message'=>$row['message'],'type'=>$row['notification_type'],'time'=>$row['created_at']],$s->fetchAll());return ['success'=>true,'notifications'=>$items];}catch(\Throwable){return ['success'=>true,'notifications'=>[]];} }
    public function checkIn(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;$id=AttendanceAccess::employeeId($a['user']);if(!$id)return ['success'=>false,'message'=>'Your employee profile is not linked.','status'=>422];$date=date('Y-m-d');if($reason=$this->restrictedReason($id,$date))return ['success'=>false,'message'=>$reason,'status'=>422];$r=Attendance::findByEmployeeAndDate($id,$date);if($r&&$r['check_in'])return ['success'=>false,'message'=>'You have already checked in today.','status'=>409];$time=date('H:i:s');$status=$time>'09:15:00'?'Late':'Present';$r=$r?Attendance::update((int)$r['id'],['check_in'=>$time,'status'=>$status,'remarks'=>null]):Attendance::create(['employee_id'=>$id,'attendance_date'=>$date,'check_in'=>$time,'status'=>$status]);return ['success'=>true,'message'=>'Checked in successfully.','record'=>$this->presentRecord($r)]; }
    public function checkOut(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;$id=AttendanceAccess::employeeId($a['user']);$r=$id?Attendance::findByEmployeeAndDate($id,date('Y-m-d')):null;if(!$r||!$r['check_in'])return ['success'=>false,'message'=>'Check in before checking out.','status'=>422];if($r['check_out'])return ['success'=>false,'message'=>'You have already checked out today.','status'=>409];if($r['break_started_at'])return ['success'=>false,'message'=>'End your break before checking out.','status'=>422];$out=date('H:i:s');$r=Attendance::update((int)$r['id'],['check_out'=>$out]+$this->hours([...$r,'check_out'=>$out]));return ['success'=>true,'message'=>'Checked out successfully.','record'=>$this->presentRecord($r)]; }
    public function startBreak(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;$id=AttendanceAccess::employeeId($a['user']);$r=$id?Attendance::findByEmployeeAndDate($id,date('Y-m-d')):null;if(!$r||!$r['check_in']||$r['check_out'])return ['success'=>false,'message'=>'An active checked-in attendance record is required.','status'=>422];if($r['break_started_at'])return ['success'=>false,'message'=>'A break is already in progress.','status'=>409];$r=Attendance::update((int)$r['id'],['break_started_at'=>date('Y-m-d H:i:s')]);return ['success'=>true,'message'=>'Break started.','record'=>$this->presentRecord($r)]; }
    public function endBreak(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;$id=AttendanceAccess::employeeId($a['user']);$r=$id?Attendance::findByEmployeeAndDate($id,date('Y-m-d')):null;if(!$r||!$r['break_started_at'])return ['success'=>false,'message'=>'No active break found.','status'=>422];$minutes=max(0,(int)floor((time()-strtotime($r['break_started_at']))/60));$r=Attendance::update((int)$r['id'],['break_minutes'=>(int)$r['break_minutes']+$minutes,'break_started_at'=>null]);return ['success'=>true,'message'=>'Break ended.','record'=>$this->presentRecord($r)]; }
    public function updateRecord(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;if(!AttendanceAccess::canManageAll($a['user']))return ['success'=>false,'message'=>'Only HR or Admin can edit attendance records.','status'=>403];$id=(int)($p['id']??0);$r=$id?Attendance::find($id):null;if(!$r)return ['success'=>false,'message'=>'Attendance record not found.','status'=>404];$in=Request::input('check_in');$out=Request::input('check_out');$status=(string)Request::input('status',$r['status']);$break=(int)Request::input('break_minutes',$r['break_minutes']);$remarks=trim((string)Request::input('remarks',$r['remarks']??''));$allowed=['Present','Absent','Late','Half Day','Work From Home','Leave','Holiday','Weekend'];if(!$this->validTime($in)||!$this->validTime($out)||($in&&$out&&$in>=$out)||!in_array($status,$allowed,true)||$break<0||$break>720||strlen($remarks)>1000)return ['success'=>false,'message'=>'Provide valid times, status, break duration and remarks.','status'=>422];$next=['check_in'=>$in?:null,'check_out'=>$out?:null,'break_minutes'=>$break,'status'=>$status,'remarks'=>$remarks?:null];$updated=Attendance::update($id,$next+$this->hours([...$r,...$next]));$this->notify($r['employee_id'],'Attendance updated','An HR/Admin user updated your attendance record.','info');return ['success'=>true,'message'=>'Attendance record updated.','record'=>$this->presentRecord($updated)]; }
    public function corrections(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;return ['success'=>true,'corrections'=>array_map([$this,'presentCorrection'],AttendanceCorrection::findMany(AttendanceAccess::visibleEmployeeIds($a['user'])))]; }
    public function createCorrection(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;$id=AttendanceAccess::employeeId($a['user']);$date=trim((string)Request::input('correction_date',''));$in=Request::input('requested_check_in');$out=Request::input('requested_check_out');$reason=trim((string)Request::input('reason',''));if(!$id||!$this->validDate($date)||$date>=date('Y-m-d')||strlen($reason)<5||strlen($reason)>1000||!$this->validTime($in)||!$this->validTime($out)||(!$in&&!$out)||($in&&$out&&$in>=$out))return ['success'=>false,'message'=>'Provide a past date, valid correction time(s), and a reason of at least 5 characters.','status'=>422];$approver=$this->approver($a['user'],$id);if(AttendanceAccess::role($a['user'])!=='ADMIN'&&!$approver)return ['success'=>false,'message'=>'No active approver is configured for your correction request.','status'=>422];$r=AttendanceCorrection::create(['employee_id'=>$id,'correction_date'=>$date,'requested_check_in'=>$in?:null,'requested_check_out'=>$out?:null,'reason'=>$reason,'submitted_on'=>date('Y-m-d'),'approver_employee_id'=>$approver]);if($approver)$this->notify($approver,'Attendance correction pending','A correction request is awaiting your decision.','warning');return ['success'=>true,'message'=>'Correction request submitted.','correction'=>$this->presentCorrection($r)]; }
    public function decideCorrection(array $p): array { $a=$this->auth();if(isset($a['success']))return $a;$id=(int)($p['id']??0);$decision=(string)Request::input('decision','');$remarks=trim((string)Request::input('remarks',''));$c=$id?AttendanceCorrection::find($id):null;if(!$c)return ['success'=>false,'message'=>'Correction request not found.','status'=>404];if($c['status']!=='Pending')return ['success'=>false,'message'=>'Only pending correction requests can be decided.','status'=>409];$me=AttendanceAccess::employeeId($a['user']);if(!AttendanceAccess::canApproveCorrection($a['user'],$c)||(!empty($c['approver_employee_id'])&&$c['approver_employee_id']!==$me))return ['success'=>false,'message'=>'You are not the assigned approver for this correction.','status'=>403];if(!in_array($decision,['Approved','Rejected'],true)||strlen($remarks)>1000)return ['success'=>false,'message'=>'Choose Approved or Rejected and keep remarks under 1000 characters.','status'=>422];$updated=AttendanceCorrection::decide($id,$decision,$remarks?:null);if($decision==='Approved'){$r=Attendance::findByEmployeeAndDate($c['employee_id'],$c['correction_date']);if(!$r)Attendance::create(['employee_id'=>$c['employee_id'],'attendance_date'=>$c['correction_date'],'check_in'=>$c['requested_check_in'],'check_out'=>$c['requested_check_out'],'status'=>'Present','remarks'=>'Attendance corrected']);else{$next=['check_in'=>$c['requested_check_in']?:$r['check_in'],'check_out'=>$c['requested_check_out']?:$r['check_out'],'remarks'=>'Attendance corrected'];Attendance::update((int)$r['id'],$next+$this->hours([...$r,...$next]));}}$this->notify($c['employee_id'],'Correction '.$decision,'Your attendance correction request was '.strtolower($decision).'.',$decision==='Approved'?'success':'warning');return ['success'=>true,'message'=>'Correction '.$decision.'.','correction'=>$this->presentCorrection($updated)]; }
}
